mapper.update:
UPDATE volunteer_activity
SET applied_count = GREATEST(applied_count + #{delta}, 0)
WHERE id = #{activityId}

mapper.select:
SELECT e.id, e.activity_id, e.user_id, CAST(e.enroll_status AS UNSIGNED) AS status, e.enroll_time AS register_time, NULL AS check_in_time, NULL AS check_out_time, 0 AS hours, COALESCE(e.audit_remark, e.enroll_remark) AS remark, u.username AS user_name, u.phone AS user_phone, a.title AS activity_title, a.address AS activity_location FROM volunteer_activity_enrollment e LEFT JOIN volunteer_user u ON e.user_id = u.id LEFT JOIN volunteer_activity a ON e.activity_id = a.id
AND e.activity_id = #{activityId}
AND e.enroll_status = #{status}
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') OR a.title LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY e.enroll_time DESC

SELECT s.id, s.activity_enrollment_id AS activityEnrollmentId, s.sign_in_time AS signInTime, s.sign_out_time AS signOutTime, CAST(s.sign_status AS UNSIGNED) AS signStatus, s.service_hour_actual AS serviceHourActual, s.confirm_user_id AS confirmUserId, s.qr_code_token AS qrCodeToken, s.create_time AS createTime, s.update_time AS updateTime, u.nickname AS userName, u.phone AS userPhone, a.title AS activityTitle, a.address AS activityLocation, e.user_id AS userId, e.activity_id AS activityId FROM volunteer_activity_sign s LEFT JOIN volunteer_activity_enrollment e ON s.activity_enrollment_id = e.id LEFT JOIN volunteer_user u ON e.user_id = u.id LEFT JOIN volunteer_activity a ON e.activity_id = a.id WHERE e.enroll_status IN ('1', '4')
AND s.sign_status = #{signStatus}
ORDER BY s.sign_in_time DESC, s.create_time DESC

SELECT COUNT(*)
FROM volunteer_activity_enrollment
WHERE enroll_status = #{status}
